impl Drop for App {
    fn drop(&mut self) {
        let _ = self.terminal_ownership.exit_terminal();
    }
}

fn send_sigint_to_pid(pid: Option<u32>) {
    #[cfg(unix)]
    if let Some(pid) = pid {
        let result = std::process::Command::new("kill")
            .arg("-INT")
            .arg(pid.to_string())
            .status();
        match result {
            Ok(status) if status.success() => {
                tracing::debug!(pid, "SIGINT sent to pi");
            }
            Ok(status) => {
                tracing::warn!(pid, ?status, "kill -INT returned non-zero");
            }
            Err(e) => {
                tracing::warn!(pid, error = %e, "failed to send SIGINT");
            }
        }
    }

    #[cfg(not(unix))]
    {
        let _ = pid;
        tracing::warn!("SIGINT not supported on this platform");
    }
}
